2139 /// to merge the attribute this way. Heuristics that would use
2140 /// min-legal-vector-width to determine inline compatibility would need to be
2141 /// handled as part of inline cost analysis.
2142 static void
2143 adjustMinLegalVectorWidth(Function &Caller, const Function &Callee) {
2144   Attribute CallerAttr = Caller.getFnAttribute("min-legal-vector-width");
2145   if (CallerAttr.isValid()) {
2146     Attribute CalleeAttr = Callee.getFnAttribute("min-legal-vector-width");
2147     if (CalleeAttr.isValid()) {
2148       uint64_t CallerVectorWidth, CalleeVectorWidth;
2149       CallerAttr.getValueAsString().getAsInteger(0, CallerVectorWidth);
2150       CalleeAttr.getValueAsString().getAsInteger(0, CalleeVectorWidth);
2151       if (CallerVectorWidth < CalleeVectorWidth)
